        ["WPN_Lightcrossbow"] = "这把别致的弓弩是由许多不同种的木料与细小铁环制成。制作者似乎想把森林里的每种树木都用上。",
        ["WPN_SourceHunter_Shield"] = "一面标准版盾牌，代表了秘源猎人骑士团中最近回归基础装备的趋势。",
        ["WPN_Wooden_Stake"] = "一根坚硬到拿来做武器的木钉，这种木钉在盗贼中常常被嘲讽为“穷人才用的匕首”。不过等吸血鬼来了，他们就笑不出来了。",
        ["WPN_Cyclops_Sword_A"] = "此剑由某种大型生物的牙齿制成，你会庆幸从来没有遇到过这样的生物。",
        ["WPN_Cudgel_B"] = "这根大铁棒外面包着厚厚的编织皮革，绑得十分结实，似乎还经常上油保养。这柄武器还真是获得了某人的悉心照料呢。",
        ["QUEST_DeathKnightKillingWand"] = "这根魔杖是唯一可以将一只状态全满的黯灵骑士直接打回虚空的武器。",
        ["WPN_Trident_C"] = "如果刺三下就有三倍的快感，那为什么只刺一下呢？",
        ["WPN_Trident"] = "如果刺三下就有三倍的快感，那为什么只刺一下呢？",
        ["WPN_MorningStar_D"] = "这柄设计繁复的战锤乃是矮人制品。从锤柄上的血迹来看，这战锤最近也经历了不少战斗。",
        ["WPN_MorningStar_C"] = "这柄设计繁复的战锤乃是矮人制品。从锤柄上的血迹来看，这战锤最近也经历了不少战斗。",
        ["WPN_Branch_A"] = "一根由浮木制成的魔杖，上面缠绕着维尼维亚人的皮革，还留有海盐的痕迹。",
        ["LOOT_Wand_D"] = "一根形状怪异的魔杖。尽管现在它还没有什么魔力，但却是一根漂亮的直木头棍！",
        ["WPN_Human_Normal_WarHammer_B_A"] = "刻在这柄战斧头部那逼真的眼珠令你感到非常不安。你无比确定每当你把视线挪开的时候，它们就会眨起眼来。",
        ["WPN_Mercygiver"] = "怜悯者匕首根据苦修的卡特里修女们命名，却可以拿来做出无比恶毒的行径。",
        ["WPN_Mercygiver_C"] = "怜悯者匕首根据苦修的卡特里修女们命名，却可以拿来做出无比恶毒的行径。",
        ["WPN_Mercygiver_B"] = "怜悯者匕首根据苦修的卡特里修女们命名，却可以拿来做出无比恶毒的行径。",
        ["WPN_Flammenschwert"] = "带有弯曲刀锋的华丽的剑。它的闪亮有如战斗中的火焰，渴望着鲜血来使火焰烧的更旺。",
        ["WPN_Flammenschwert_C"] = "带有弯曲刀锋的华丽的剑。它的闪亮有如战斗中的火焰，渴望着鲜血来使火焰烧的更旺。",
        ["WPN_Flammenschwert_B"] = "带有弯曲刀锋的华丽的剑。它的闪亮有如战斗中的火焰，渴望着鲜血来使火焰烧的更旺。",
        ["WPN_Wand_Air_I"] = "一只充满了静电能量的魔杖，即使是轻轻的碰触，也足以令你的手指因触电而颤抖。",
        ["WPN_Arrow_Debuff_All_A"] = "一支诅咒箭，犹如女巫的亲吻，可以汲取任何敌人的力量。",
        ["WPN_FlangedMace_C"] = "这柄钉头锤那锋利如箭般的头部镶嵌着羽毛，它被称为“费诺之羽”。通常它被作为费诺的贵族所使用的仪仗武器。",
        ["WPN_FlangedMace_B"] = "这柄钉头锤那锋利如箭般的头部镶嵌着羽毛，它被称为“费诺之羽”。通常它被作为费诺的贵族所使用的仪仗武器。",
        ["WPN_FlangedMace"] = "这柄钉头锤那锋利如箭般的头部镶嵌着羽毛，它被称为“费诺之羽”。通常它被作为费诺的贵族所使用的仪仗武器。",
        ["WPN_Luculla_Prostitute_Guitar"] = "音乐虽然可以作为促进爱情的食粮，但若是在热恋期，即使作为佐料也是远远不够的。这把乐器经常可以用来生产刚刚提到的“佐料”，或是让一旁的路人慷慨解囊。",
        ["WPN_Quarterstaff_Earth"] = "这把强健的法杖似乎是用新鲜树木制成的。杖身还有不少嫩枝和叶芽，一个绿色的魔力光环在端部放射着能量。",
        ["WPN_ArrowShaft_A"] = "一根十分完美的箭柄，配上一个特殊的箭头，便可以对敌人施加强大的伤害和各种各样的效果。",
        ["WPN_DarkMinions_BigSword_A"] = "这些剑是莉安德拉的部队的骄傲；黑暗带来的快感将会使他们被铭记在一代又一代秘源法师的脑海中。",
        ["WPN_Wand_Fire_E"] = "这只称手的魔杖不时地闪耀出幽灵般的火光，静静地听，你能听到火焰中火花爆裂的噼啪声。",
        ["WPN_ShortBow"] = "一张古典款式和现代构造相结合的精灵弓。搭弦处的V字型深槽是为了向著名的沃迪斯蒂斯射手致敬。",
        ["WPN_LongSword"] = "铸以激情，精准调质，这把利剑该如何发挥用处则取决于你。",
        ["WPN_ShortSword"] = "铸以激情，精准调质，这把利剑该如何发挥用处则取决于你。",
        ["WPN_Human_Normal_Mace_B"] = "一种特制的，用来击穿重装敌人的护甲的铜头钉头锤，就算是身披链甲也难以抵挡它连续的攻击。",
        ["WPN_Human_Normal_Mace_A"] = "一种特制的，用来击穿重装敌人的护甲的铜头钉头锤，就算是身披链甲也难以抵挡它连续的攻击。",
        ["WPN_Branch_A_Nails"] = "你之前也曾看到过人们使用这种武器。当然，他们都是无恶不作的强盗，但这也不能代表不是强盗就不能用啊！",
        ["WPN_CysealGuardBow"] = "一把鬼鬼祟祟的弓缠着紧绷的弓弦，你永远也听不够当它放箭时所发出的那一声嘣响。",
        ["WPN_Wand_Earth_E"] = "这根魔杖看来是从一颗活生生的大树上切下来的。它的尖端还长着新芽和嫩叶。",
        ["LOOT_Wand_A"] = "一根外观独特的魔杖。尽管现在它还没有什么魔力，但仍是一根漂亮的直木棍！",
        ["WPN_Wand_Shadow"] = "这根魔杖笼罩在一片黑云之中，看起来就像是由黑暗本身雕刻而成的。",
        ["WPN_Gada"] = "这件武器由黑刺橡木雕琢而成，把手格外沉重。它总是能创造出新的秩序。",
        ["WPN_CraftedSword_SwordOfPlanets"] = "使用泥土与鲜血混铸而成的独特武器。仔细看看那磨得闪闪发亮的锋刃吧，你能看到星星在其中向你眨眼吗？",
        ["WPN_Wand_Fire_M"] = "这根魔杖顶部镶嵌着一颗深红色的宝石，近距离细看可以发现里面有一团永远烧不完的余烬。",
        ["WPN_Imps_2H_Spear_A"] = "坊间传说认为小鬼一族现在都独自藏匿着，并悄悄为自己打造锋利的长矛。他们对于这种长矛的传统设计，是基于小鬼们当年那战争中的回忆。",
        ["WPN_Blackrock_Axe_A"] = "注入黯金之力的战斧。这把铸有珍贵矿料的战斧十分凶险，只有真正精于斗技的人才能安全使用。",
        ["WPN_Luculla_Prostitute_Sword"] = "一柄看起来十分华美昂贵的剑。剑刃上用金丝镶嵌着“向我们的卡尔迪亚骑士致敬”的字样。嗯。",
        ["WPN_Undead_2H_Axe_Braccus_A"] = "重生国王布拉克斯·雷克斯的恐怖巨斧千年来斩下了无数敌人的首级。",
        ["WPN_HeadingSword2H_B"] = "维尼维亚的战士特有的剑，被战争遗忘的人戏称它为“战士的情人”。",
        ["WPN_Claymore_2H_E"] = "维尼维亚的战士特有的剑，被战争遗忘的人戏称它为“战士的情人”。",
        ["WPN_Claymore_2H"] = "维尼维亚的战士特有的剑，被战争遗忘的人戏称它为“战士的情人”。",
        ["WPN_HeadingSword2H"] = "维尼维亚的战士特有的剑，被战争遗忘的人戏称它为“战士的情人”。",
        ["WPN_Claymore_2H_C"] = "维尼维亚的战士特有的剑，被战争遗忘的人戏称它为“战士的情人”。",
        ["WPN_HeadingSword2H_C"] = "维尼维亚的战士特有的剑，被战争遗忘的人戏称它为“战士的情人”。",
        ["WPN_Blackrock_2H_Sword_A"] = "你需要双手才能把这黯金剑高高举起，最好确定你知道它的正确使用方式。",
        ["WPN_Blackrock_Shield_A_A"] = "让敌人不敢正视的黯金盾甚至在战斗开始之前就能让所有人都感受到其身上散发出的王霸之气。",
        ["WPN_ArrowHead_Poison_A"] = "一支透着邪恶气息的箭头，披着剧毒的外衣仿佛毒蛇般吐着信子嘶嘶作响。制作这东西的时候尽量不要吸气。",
        ["WPN_ArrowHead_Silver_A"] = "把精致的银线附着在一支箭的箭头上似乎有点浪费。不过，也许它华丽的外表下同样有十足的破坏力...",
        ["WPN_Orcs_Shaman_Staff_A_Fighting_Staff_Fire"] = "燧石绑在木棍上就制成了这只萨满武器。神秘的兽人魔法从这根木棍的每一个裂纹和燧石的瑕疵中不断渗出。",
        ["WPN_Sword_A_Poisoned_Training_Sword"] = "一把形如蟒蛇的剑，一滴发光的毒液从其顶端落到地面并发出嘶嘶的声音。",
        ["WPN_Leandra_Staff_A"] = "这法杖就像莉安德拉的心一样在燃烧，激情的火焰慢慢被憎恨所侵蚀。",
        ["WPN_Blackrock_2H_Spear_A"] = "在战斗时，这支头上顶着闪闪发亮的黯金尖刺的长矛能对敌人造成的伤害绝对比你对他们喋喋不休的谩骂要高。",
        ["WPN_Sword_Tenebrium_A"] = "从剑柄到剑尖，都由最纯正的黯金打造而成，对它的敌人异常致命...可能就连使用者都难逃一劫。",
        ["WPN_BastardSword_B"] = "它的锋刃上有缺口和擦伤，这件沉重的破腹武器是绝佳的伙伴，不论是用于交易、威胁，还是普通的恐吓。",
        ["WPN_BastardSword_C"] = "它的锋刃上有缺口和擦伤，这件沉重的破腹武器是绝佳的伙伴，不论是用于交易、威胁，还是普通的恐吓。",
        ["WPN_BastardSword"] = "它的锋刃上有缺口和擦伤，这件沉重的破腹武器是绝佳的伙伴，不论是用于交易、威胁，还是普通的恐吓。",
        ["WPN_Goblins_Bow_A_Hunter"] = "一柄东拼西凑匆忙赶制的长弓。奇怪的是，这把弓射出的箭还是十分精准，威力也不可小觑。",
        ["WPN_ArrowHead_Explosive_A"] = "这箭头极度易燃，能发出各种噪音，它在你背包里呆的时间越短越好。",
        ["WPN_Wand_Earth_I"] = "这支法杖上爬满了小蜘蛛，偶尔会消失于看起来中空的木棍上的小洞中。这些蜘蛛的存在似乎会增强法杖的效果而不会削弱它。",
        ["WPN_DIY_Axe_A"] = "一把可以当做武器用的普通伐木斧。尽管拥有一切“纯手工打造”的缺点，但仍然非常实用。",
        ["WPN_Wand_Fire_I"] = "这根燃烧着的魔杖中蕴藏的熊熊业火，在你接触它时突然变得温和了起来，可是一旦碰到敌人，它的烈焰之力便会顷刻之间令他们烧灼殆尽。",
        ["WPN_Kickstarter_StaffOfImagination"] = "这件超级强大的魔法物品可以让你美梦成真，如果你的梦想是摧毁一切的话。传说这把法杖是由神秘法师索罗马丁利用自己的思维的一部分打造的，他的原意是希望造出最强大的建设工具。但结果它却只会破坏。",
        ["WPN_Glaive_2H"] = "一把由纯粹的怨念与憎恶融入其中铸造而成的巨斧，简直是为你量身打造的！",
        ["WPN_Glaive_2H_C"] = "一把由纯粹的怨念与憎恶融入其中铸造而成的巨斧，简直是为你量身打造的！",
        ["WPN_Glaive_2H_B"] = "一把由纯粹的怨念与憎恶融入其中铸造而成的巨斧，简直是为你量身打造的！",
        ["WPN_Arrow_SlowDown_A"] = "这种箭会令它的目标步履维艰，你面对他们行动起来时就仿佛踩着弹簧一般。",
        ["WPN_Kickstarter_SwordOfHolyFlame"] = "几个世纪之后，这把剑将由长老之火铸造。它将会被一位传奇的龙骑士使用，来重建一个濒临灭亡的失落帝国。这是唯一一把已知的从过去未来到现在的剑。",
        ["WPN_ArrowHead_Charming_A"] = "这个箭头有如一个可爱的护身符。完全可以用它来制作一支厉害的长箭。当然，在这之前要先下定决心舍弃这么一个宝贝。",
        ["WPN_Arrow_Silver_A"] = "快看这美人儿多么精致！精雕细琢的木料，加上狂野嗜血的尖头，这箭简直是绝世上品啊。",
        ["WPN_Human_Normal_Buffalo_Sabre_A"] = "一个复杂的水牛头图案镌刻在这把非比寻常的军刀的刀柄上。",
        ["WPN_Cyclops_Staff_A_Scythe"] = "这柄法杖巨大又不合手，似乎寻常人类拿起来都费劲的很，更别说用它战斗了。",
        ["WPN_ArrowHead_Freezing_A"] = "闪闪发光的箭头，表面上永远都有露珠凝结。如果没有用它打造一支特殊的箭矢，你也可以拿去冰镇你的饮品。",
        ["WPN_Steelcrossbow"] = "这柄弩整体采用的金属材质远多于木材，而且还注入了不少的法汉吉特精华，打起人来疼得要命呢。",
        ["WPN_DIY_Staff_B"] = "一把造型粗糙、质量一般的法杖。没什么特别的。",
        ["WPN_Wand_Shadow_E"] = "这根阴森的魔杖被一层黑暗的阴影笼罩着，轻声低语着你不想听到的秘密。",
        ["WPN_Luculla_Prostitute_Stick"] = "一根普通的木棒，与其说它是武器，倒不如说是木柴更恰当一些。",
        ["WPN_ArrowHead_A"] = "一只无比平凡的箭头。将箭头与其它物品组合以制造特殊箭头。",
        ["WPN_DIY_Bow_A"] = "一支看起来像是小孩子用十只指头削出来的弓，虽然看起来很粗糙，但勉强还能用。",
        ["WPN_Wollocks_Shield_A"] = "这个盾牌用你噩梦中最可怕的梦境装饰而成，最好锁在阁楼上最阴暗的橱柜里。",
        ["WPN_DIY_Bow_D"] = "一把能像竖琴一样发出嗖嗖响声的弓，每支从这把弓上射出的利箭都好似裹挟着绝望。",
        ["WPN_Sword_Kickstarter_Japanese"] = "这把剑似乎是来自另一个星球，也有可能是来自另一维度。剑柄刻有“致彼得·李。日本制造”这人名地名让你完全摸不着头脑。",
        ["WPN_Arrow_A"] = "你确定吗？普普通通的箭矢到处都是，但特殊的箭矢却十分罕见。在你制作箭矢之前，请先尝试使用不同的材料来加工你的箭头。",
        ["WPN_Arrow_Poison_A"] = "仔细观察：这种箭矢和普通箭矢的唯一可见区别只有箭头上的凹痕。",
        ["WPN_Wand_Earth"] = "这把法杖满是尘土，散发着一股浓厚的土壤味道。",
        ["WPN_ArrowHead_Steam_A"] = "虽说这箭头听起来动静比卡尔迪亚蒸气浴都大，但把这玩意插在箭柄上射出去，威力可是十分惊人。",
        ["WPN_Blackrock_Shield_B_A"] = "一面由黯金捆扎而成的盾牌。覆盖在表面的毁灭纹章展示着它的力量。但你能驾驭它吗？",
        ["WPN_PeasantsBlackBillPolearm_2H"] = "原本是虔诚的卡哈教团在仪式中使用的仪仗器，后来被用在了战场上。它从远处发出的每一次挥击，都会让初见者叫苦不迭。",
        ["WPN_Scimitar_B"] = "绑在这把银月弯刀握柄上的祖母绿宝石告诉了人们这把武器的来由。它曾在阿祖尔海滩的那些佣兵手中书写传奇。",
        ["WPN_Scimitar_C"] = "绑在这把银月弯刀握柄上的祖母绿宝石告诉了人们这把武器的来由。它曾在阿祖尔海滩的那些佣兵手中书写传奇。",
        ["WPN_DIY_Axe_C"] = "一把渴望敌人鲜血洗礼的高级战斧。砍掉他们的头吧！",
        ["WPN_DIY_Sword_C"] = "满怀热情细致打造的一把高品质剑。闪闪发亮，甚至都可以当镜子用了。",
        ["WPN_Wand_Air_M"] = "当你高高举起这根魔杖时，火花就会从杖头上喷溅而出，召唤着苍穹的神力。",
        ["WPN_Arrow_Stunning_A"] = "注入了气之狂怒的箭。如果仔细聆听，你可以听见它跃跃欲试的呼啸声和翻腾声。",
        ["WPN_Rapier_A"] = "这是一把庄严的利刃！一位真正的绅士在用膳时便会将其从腰间卸下。但可能在他饭还没吃完时，就被觊觎这把利刃的小人背刺而亡。",
        ["WPN_DIY_Staff_C"] = "由上等的木头雕刻而成的精美物品，上面蚀刻着你的名字的首字母。愿子子孙孙永世怀念你。",
        ["WPN_Quarterstaff_Henchman_Jahan"] = "一根样式极其古老的法杖，或许现在除了在博物馆，其它地方是再也找不到第二根了。",
        ["WPN_DIY_Sword_B"] = "品质一般的粗制剑。可以突刺，可以劈砍。如果你想更拉风一点的话，还是考虑考虑别的剑吧。",
        ["WPN_Arrow_Poison_Cloud_A"] = "一把锋利的箭头在一团绿色毒雾下闪闪发光。当你释放这股毒雾时，最好屏住呼吸。",
        ["WPN_DIY_Axe_D"] = "无比威猛的战斧，就连西格德本人都会爱不释手。干得好。",
        ["WPN_Human_Normal_Scythe_A"] = "这把镰刀被农夫改造过，使其更加适用于战斗，虽然看起来朴实无华，可它砍掉的脑袋比收割过的麦子还多。",
        ["WPN_DIY_Sword_D"] = "一把威力强大的家传宝剑，适合挂在壁炉架上。当然，先让它见见血也不错。",
        ["WPN_KnobbedMace_B"] = "这柄钉头锤就是那种抡到谁身上，你一眼就能看出他已经完蛋了的武器。",
        ["WPN_Orcs_Warrior_Sword_A"] = "一把让你产生对那个没有锻造、艺术和技能的旧时代的怀旧之情的剑。",
        ["WPN_DarkMinions_DoubleAxe"] = "一柄黑暗而恐怖的斧子。不可思议的是一面的刃状况远好于另一面。",
        ["WPN_Rapier_B"] = "这是一把庄严的利刃！一位真正的绅士在用膳时便会将其从腰间卸下。但可能在他饭还没吃完时，就被觊觎这把利刃的小人背刺而亡。",
        ["WPN_Rapier_C"] = "这是一把庄严的利刃！一位真正的绅士在用膳时便会将其从腰间卸下。但可能在他饭还没吃完时，就被觊觎这把利刃的小人背刺而亡。",
        ["WPN_UNIQUE_AstarteCandle"] = "样一年当蒂塔斯阿如就亮明此如焰火这。",
        ["WPN_Wand_Air_E"] = "这根法杖显露出强大的威力并一直劈啪作响，它预示着暴风的力量。",
        ["WPN_Wollocks_Staff_A_SkullHorns_Earth"] = "除了那饰纹骷髅空洞眼眶的凝视之外，这根萨满法杖还有其它可怕之处。各种小饰品，羽毛，咒文——别人见到肯定要吓尿。",
        ["GRN_Ingredient_Holy_Empty"] = "这颗设计复杂的球体表面，饰有纷乱繁杂的金丝，看看就觉得肯定不便宜。上面用精致的字体写着：“摒弃俗世之财者，神将保其健康长寿。”那是当然的。",
        ["WPN_DIY_Staff_D"] = "一把用最好的木材打造，以最厉害的符咒装饰的法杖，你的敌人们或许会嘲笑它难看的长相，但这也证明他们离死期已经不远了。",
        ["WPN_ArrowHead_Antler_A"] = "传说一箭之力便可制服一头牡鹿。把这箭头跟一根箭柄连上，你便可验其真伪。",
        ["GRN_Ingredient_Round_Empty_A"] = "用厚厚的易碎的岩石制成的两只半球体。它们现在是空的，那为什么不加点激动人心的东西进去呢？",
        ["WPN_Goblins_Staff_A_BlueGlowStaff_Earth"] = "以常见的古怪之物装饰的萨满权杖。别的不说，哥布林确实很懂得怎么装饰。",
        ["WPN_Wand_Air"] = "此魔杖会在你挥动它时发出鸣响——奏出一曲伴着和风的思乡之歌。",
        ["WPN_ArrowHead_SlowDown_A"] = "敌人的速度对你来说太快了吗？把这只做工精良的箭头装在箭柄上，你就再也不用担心抽箭速度慢了。",
        ["WPN_Arrow_Fire_A"] = "摸上去很烫的火焰箭。如果想保证安全最好让它远离油之类的物品。",
        ["WPN_DarkMinions_SingleAxe"] = "尽管这金属上满是裂痕，它看上去仍被一股黑暗的涌动之力聚合在一起。",
        ["WPN_Blackrock_Scythe_A"] = "这把镰刀犹如龙爪般险恶。举起它对你来说同样致命... 除非你能证明自己有资格去挥舞它。",
        ["WPN_Scimitar"] = "绑在这把银月弯刀握柄上的祖母绿宝石告诉了人们这把武器的来由。它曾在阿祖尔海滩的那些佣兵手中书写传奇。",
        ["WPN_Unique_Heartseeker"] = "你一定从未见过这么美丽的弓吧。雕工精致，抛光细腻。用它瞄准的时候，你视野里的一切都变得异常清晰。",
        ["WPN_DIY_Sword_A"] = "一把士兵们上第一堂训练课时所用的剑，或许用来应应急还不错。",
        ["WPN_Arrow_Charming_A"] = "这支可爱的小箭矢被注入了魅惑药剂，非常独特。你真的真的真的很喜欢它。",
        ["WPN_Blackrock_Bow_A"] = "一把需要极其高超的技巧才能掌控的弓，黯金的斑点加强了弓的性能和你的决心。",
        ["WPN_Wand_Water_E"] = "当你握着这根魔杖时它湿漉漉的。然而，你一旦使用就会目睹洪水般的魔法从它的末端源源不断地涌出。",
        ["WPN_Blackrock_2H_Axe_A"] = "使用一大块黯金凿出来的一把斧头，对于不精通黯金武器的使用者来说是个灾难。",
        ["WPN_PoleCleaver_2H_B"] = "石头与钢铁之灵合在一处才产生了这把无坚不摧的利斧。作为回礼，你需要献上自己双手的力量才能挥得动它。",
        ["WPN_PoleCleaver_2H_C"] = "石头与钢铁之灵合在一处才产生了这把无坚不摧的利斧。作为回礼，你需要献上自己双手的力量才能挥得动它。",
        ["WPN_PoleCleaver_2H"] = "石头与钢铁之灵合在一处才产生了这把无坚不摧的利斧。作为回礼，你需要献上自己双手的力量才能挥得动它。",
        ["WPN_Trolls_2H_Staff_IceKing_A"] = "凛冬之王波瑞阿斯国王的法杖散发着冰冷的能量。纤细的冰晶就像针芒一样，从杖尖向着各个方向四散开来，所碰之物皆会冻结成冰。",
        ["WPN_ArrowHead_Stunning_A"] = "这个箭头展现出极佳的工艺，确实很棒。",
        ["WPN_Wand_Earth_M"] = "一只由不寻常的木头雕琢而成，自相缠绕编织的双生魔杖，它的顶端镶嵌着闪闪发亮的琥珀。在那琥珀中，有一只蚂蚁被永远地剥夺了自由。",
        ["WPN_Human_Normal_Sabre_A_Rusty"] = "一柄很独特的军刀，上面有些地方已经生锈了，但在它锈蚀的表面下的刀刃却崭新如初。",
        ["WPN_Arrow_SmokeScreen_A"] = "这把剑是根据从卡拉维的编年史中秘密偷出来的秘方制造而成的，卡拉维是一群由神出鬼没的盗贼组成的团体。",
        ["GRN_Ingredient_Fuse_A"] = "对于手雷的制作者来说，引线就是他们最大的乐趣：引线可以从商人那里买来，也可以翻箱倒柜来寻找，它们随处可见！当然，*最*有趣的还是点燃引线的时刻！",
        ["WPN_Blackrock_Hammer_A"] = "完美的黯金武器需要反复捶打。",
        ["WPN_Arrow_Freezing_A"] = "冰霜箭矢，可以深深插入敌人的肉体，冰冻住他们。",
        ["WPN_Wand_Water"] = "水滴陆续不断地从魔杖的末端缓缓滴落，渐渐在你的所经之路上留下一片繁花与灌木。",
        ["GRN_Ingredient_Love_Empty_A"] = "一个空的香水瓶，里面还隐约飘出一丝残留的令人陶醉的芬芳。当下你唯一的愿望就是一辈子都可以这样闻下去。",
        ["WPN_UNIQUE_SeaSpiderClaw"] = "这是从一只噩梦般的憎恶身上扯下来的残忍武器。",
        ["GRN_Ingredient_Cylinder_Empty_A"] = "一个空的，球形的圆筒，塞着锈迹斑斑且已经褪色的铜片。上面压印着的金属锻造工标记表明这件物品产自某个遥远的军工厂。",
        ["WPN_DIY_Bow_C"] = "一流的弓，弓身由优质木材打造，弓弦由紧绷的皮筋制成，在战斗中会成为你的好伙伴。",
        ["LOOT_Wand_C"] = "一根很有前途的魔杖。尽管现在它还没有什么魔力，但仍是一根漂亮的直木棍！",
        ["WPN_Luculla_Prostitute_Log"] = "这明显就是把一根树桩拿来直接当做武器使。你其实能做得比这个好的，不是吗？",
        ["WPN_Quiver_A_Normal_Arrows"] = "坚固的缝纫技术与上好的皮革料子使你的箭在此箭袋里得到了妥善的保管。",
        ["WPN_Trolls_2H_Staff_IceKing_A_Human"] = "手持海伯海姆的藤条时，水流的活力充满了你的全身，并凝固成了冰一样坚固的意志。",
        ["WPN_Arrow_Explosive_A"] = "这种名为“龙之箭”的装备由著名的拉比特拉的弓箭手们使用，这支爆炸箭头能在击中敌人时瞬间产生耀眼的爆炸。",
        ["WPN_Arrow_KO_A"] = "灌铅的箭矢太沉了，重得都几乎难以射击。",
        ["WPN_Blackrock_Crossbow_A"] = "制造的专家昵称其为“蜂后”，黯金弩如蜂后的蜂刺般稀有，堪称是个传说。",
        ["WPN_Blackrock_DaggerPush_A"] = "黯金匕首是卡拉维刺客的最爱，匕首嗡嗡的声响具有巨大的内在潜力。",
        ["WPN_Wand_Fire"] = "一根被幻影火焰环绕的闪闪发光的魔杖。它在你的手中散发着温暖，仿佛它的核心是用发光的煤炭制成的。",
        ["WPN_ArrowHead_Poison_Cloud_A"] = "你最好把这个仔细收好。绿维珑的酒馆怪谈里经常会提到发生在可怜的艾格瑞德身上的悲剧，他的死，肯定与那天不小心坐到装有这种东西的箭袋上有关。",
        ["WPN_DIY_Staff_A"] = "一支普通的法杖，准确来说是一支稍微打磨过的木棍，真的。",
        ["WPN_Quarterstaff_Air"] = "在这支法杖顶端有一阵永不止息的暴风，无数电闪从中迸发而出。如果将其高高举起，便能听到它与风声和鸣。",
        ["WPN_Wand_Water_M"] = "除了你的皮肤之外，这把魔杖会冻结一切它所触碰的物品。如果对水洼使用，还可以用来恶作剧。",
        ["WPN_DecorationSword_Henchman_Madoc"] = "一把经过各种小饰物精心装饰、擦得锃光瓦亮的精良的长剑。看来它的前主人是对其爱惜有加啊。",
        ["WPN_ArrowHead_Static_Could_A"] = "一个小小的瓶子，雷暴的声音在其中嘶嘶作响。若能将它灌入一种特殊的箭头，便可在战场上施展雷霆般的攻势。",
        ["WPN_DIY_Bow_B"] = "质量一般的简单弓箭。眯起眼仔细打量一番，可能会觉得其实还不错。",
        ["WPN_UNIQUE_Gungir_Morningstar"] = "巨魔王最喜爱的玩具，其大小刚好可以被人类的手抓握住。",
        ["WPN_Luculla_Prostitute_Dagger"] = "一把形如一条扭动的毒蛇，闪耀着寒光的匕首。藏于无良女性的胸间再合适不过。",
